"""SentriX dashboard adapter for the real unified V2 production DOM.

V4/V5/V6 were originally written against the pre-V55 DOM (``#serverContent`` / ``#fields``).
Production V55 serves ``dashboard_unified_v2`` instead, whose stable anchors are ``.workspace``
and ``#content``.  This layer is intentionally presentation-first and reuses the existing
backend/routes; the verification publish action explicitly saves the unified V2 selections,
then calls the real V96 dashboard route.
"""
from __future__ import annotations

import logging

logger = logging.getLogger("bot.dashboard-unified-adapter-v9")

