V9_JS = r'''
<script id="sentrix-unified-adapter-v9-js">
(()=>{"use strict";if(window.__sentrixUnifiedAdapterV9)return;window.__sentrixUnifiedAdapterV9=true;
const $=id=>document.getElementById(id),S=()=>{try{return state}catch(_){return null}},fmt=n=>Number(n||0).toLocaleString("fr-FR");
const META={overview:["OV","Vue d’ensemble","Santé, activité et raccourcis essentiels du serveur."],welcome:["AD","Arrivées & départs","Parcours d’arrivée, départs et automatisations d’accueil."],levels:["NV","Progression","XP, niveaux et annonces de progression."],security:["SE","Protection active","AutoMod, anti-raid et permissions critiques."],moderation:["MO","Modération","Historique disciplinaire et actions administratives."],logs:["LG","Journalisation détaillée","Destinations, catégories et suivi des événements Discord."],verification:["VE","Vérification Discord","Règlement, CAPTCHA réel et attribution du rôle membre."],roles:["RO","Architecture des rôles","Rôles automatiques, staff et permissions utilisées par SentriX."],economy:["EC","Économie","Comptes persistants et accès aux fonctions économiques."],notifications:["NO","Diffusion sociale","Sources et destinations YouTube, TikTok, Twitch et autres."],tickets:["TI","Support structuré","Panels, types, publication et suivi des tickets."],ai:["AI","Moteur IA","Modèle, mémoire, limites et journalisation."],embeds:["EM","Embeds & design","Création et aperçu des messages Discord."],config:["CF","Configuration","Fondations et paramètres principaux du serveur."],access:["AC","Accès & commandes","Portée, commandes et gestionnaires SentriX."],diagnostic:["DG","Santé & diagnostic","Permissions, ressources cassées et état réel du serveur."]};
function info(){const t=S()?.tab||"overview";return META[t]||["SX","SentriX","Configuration du serveur."]}
function ensureHero(){const s=S(),ws=document.querySelector(".workspace"),head=ws?.querySelector(".workspace-head");if(!s?.guildData||!ws||!head)return;if(s.tab==="overview"){$("sxUnifiedHeroV9")?.remove();return}let hero=$("sxUnifiedHeroV9");if(!hero){hero=document.createElement("section");hero.id="sxUnifiedHeroV9";head.insertAdjacentElement("afterend",hero)}$("sxUnifiedKpisV9")?.remove();const i=info(),sig=[s.tab,s.guildId].join("|");if(hero.dataset.sig===sig)return;hero.dataset.sig=sig;hero.innerHTML=`<div class="sxv9-hero-main"><div class="sxv9-icon">${i[0]}</div><div class="sxv9-copy"><div class="sxv9-kicker">SentriX Control Center · V9</div><h2>${i[1]}</h2><p>${i[2]}</p></div></div><div class="sxv9-actions"><span class="sxv9-live">Temps réel</span><button class="btn" type="button" id="sxV9Refresh">Actualiser</button><button class="btn" type="button" id="sxV9Diagnostic">Diagnostic</button></div>`;$("sxV9Refresh")?.addEventListener("click",()=>{try{if(typeof refreshAll==="function")refreshAll()}catch(_){location.reload()}});$("sxV9Diagnostic")?.addEventListener("click",()=>{try{if(typeof go==="function")go("diagnostic")}catch(_){}})}
async function req(path,opt={}){const s=S(),headers={...(opt.headers||{})};if(opt.method&&opt.method!=="GET")headers["X-CSRF-Token"]=String(s?.csrf||"");if(opt.body)headers["Content-Type"]="application/json";const r=await fetch(path,{credentials:"same-origin",cache:"no-store",...opt,headers});let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw new Error(d.error||`Erreur HTTP ${r.status}`);return d}
function copyOptions(from,to){if(!from||!to)return;to.innerHTML=from.innerHTML;to.value=from.value}
async function loadVerifyState(){const s=S(),box=$("sxV9VerifyStatus");if(!s?.guildId||!box)return;try{const d=await req(`/api/guilds/${encodeURIComponent(s.guildId)}/verification-v6`);box.className="sxv9-verify-status "+(d.published?"ok":"");box.textContent=d.published?`Panneau actif sur Discord${d.channel_name?` · #${d.channel_name}`:""}${d.role_name?` · @${d.role_name}`:""}`:"Prêt à configurer puis publier sur Discord.";if(!$("sxV9Title")?.dataset.touched)$("sxV9Title").value=d.title||"Règlement & vérification";if(!$("sxV9Rules")?.dataset.touched)$("sxV9Rules").value=d.rules_text||$("verifyRules")?.value||"";if(!$("sxV9Image")?.dataset.touched)$("sxV9Image").value=d.image_url||$("verifyImage")?.value||"";if(!$("sxV9Auto")?.dataset.touched)$("sxV9Auto").checked=!!d.auto_access;const b=$("sxV9Publish");if(b)b.textContent=d.published?"Mettre à jour sur Discord":"Publier sur Discord"}catch(e){box.className="sxv9-verify-status bad";box.textContent=e.message}}
async function publishVerify(){const s=S(),btn=$("sxV9Publish"),box=$("sxV9VerifyStatus");if(!s?.guildId||!btn)return;const channel=$("sxV9Channel")?.value||"",role=$("sxV9Role")?.value||"",rules=$("sxV9Rules")?.value||"",image=$("sxV9Image")?.value||"",captcha=!!$("sxV9Captcha")?.checked,tries=Number($("sxV9Tries")?.value||3);if(!channel||!role){box.className="sxv9-verify-status bad";box.textContent="Choisis le salon et le rôle avant de publier.";return}btn.disabled=true;box.className="sxv9-verify-status";box.textContent="Enregistrement puis publication Discord…";try{if(typeof v62Action!=="function")throw new Error("Le moteur de configuration unifié n’est pas chargé.");await v62Action({action:"verification_save",channel_id:channel,role_id:role,rules_text:rules,image_url:image,captcha_enabled:captcha,captcha_max_attempts:tries,publish:false});const d=await req(`/api/guilds/${encodeURIComponent(s.guildId)}/verification-v6/publish`,{method:"POST",body:JSON.stringify({title:$("sxV9Title")?.value||"Règlement & vérification",rules_text:rules,image_url:image,auto_access:!!$("sxV9Auto")?.checked})});box.className="sxv9-verify-status ok";box.textContent=d.message||"Panneau de vérification publié sur Discord avec CAPTCHA.";try{if(typeof toast==="function")toast(box.textContent)}catch(_){}await loadVerifyState()}catch(e){box.className="sxv9-verify-status bad";box.textContent=e.message;try{if(typeof toast==="function")toast(e.message,true)}catch(_){}}finally{btn.disabled=false}}
function mountVerification(){if(S()?.tab!=="verification")return;const content=$("content"),grid=content?.querySelector(":scope > .grid")||content;if(!grid||$("sxVerifyV9"))return;const oldChannel=$("verifyChannel"),oldRole=$("verifyRole"),oldRules=$("verifyRules"),oldImage=$("verifyImage"),oldCaptcha=$("verifyCaptcha"),oldTries=$("verifyTries");oldChannel?.closest(".card")?.classList.add("sx-v9-hidden-legacy-verify");const card=document.createElement("section");card.id="sxVerifyV9";card.innerHTML=`<div class="sxv9-verify-head"><div><h3>Vérification Discord réelle</h3><p>Publie le règlement dans Discord. Le membre clique sur le bouton SentriX, résout le CAPTCHA, puis reçoit le rôle choisi uniquement après réussite.</p></div><span class="sxv9-captcha-badge">CAPTCHA V96 RÉEL</span></div><div class="sxv9-verify-grid"><div class="sxv9-vfield"><label>Salon de vérification</label><select id="sxV9Channel"></select></div><div class="sxv9-vfield"><label>Rôle après réussite</label><select id="sxV9Role"></select></div><div class="sxv9-vfield full"><label>Titre du panneau</label><input id="sxV9Title" maxlength="100" value="Règlement & vérification"></div><div class="sxv9-vfield full"><label>Règlement</label><textarea id="sxV9Rules" maxlength="4000"></textarea></div><div class="sxv9-vfield full"><label>Image HTTPS facultative</label><input id="sxV9Image" type="url" maxlength="500" placeholder="https://…"></div></div><div class="sxv9-verify-options"><label><input id="sxV9Captcha" type="checkbox" checked> CAPTCHA obligatoire</label><label>Tentatives <input id="sxV9Tries" type="number" min="1" max="10" value="3" style="width:58px"></label><label><input id="sxV9Auto" type="checkbox"> Gérer automatiquement l’accès aux salons publics</label></div><div class="sxv9-verify-actions"><button class="btn primary" id="sxV9Publish" type="button">Publier sur Discord</button><button class="btn" id="sxV9VerifyRefresh" type="button">Actualiser</button><div id="sxV9VerifyStatus" class="sxv9-verify-status">Chargement de l’état Discord…</div></div>`;grid.prepend(card);copyOptions(oldChannel,$("sxV9Channel"));copyOptions(oldRole,$("sxV9Role"));$("sxV9Rules").value=oldRules?.value||"";$("sxV9Image").value=oldImage?.value||"";$("sxV9Captcha").checked=oldCaptcha?oldCaptcha.checked:true;$("sxV9Tries").value=oldTries?.value||3;["sxV9Title","sxV9Rules","sxV9Image","sxV9Auto"].forEach(id=>$(id)?.addEventListener("input",e=>e.currentTarget.dataset.touched="1"));$("sxV9Publish")?.addEventListener("click",publishVerify);$("sxV9VerifyRefresh")?.addEventListener("click",loadVerifyState);loadVerifyState()}
function decorate(){const s=S();if(!s)return;const b=document.body,tab=s.tab||"overview";/* n'écrire que si la valeur change : un setAttribute identique déclenche quand même les MutationObserver (V27 relançait l'animation de page toutes les 1,5 s) */if(b.dataset.sxDashboardV9!=="1")b.dataset.sxDashboardV9="1";if(b.dataset.sxTab!==tab)b.dataset.sxTab=tab;ensureHero();mountVerification()}
function start(){decorate();const content=$("content");if(content)new MutationObserver(()=>setTimeout(decorate,0)).observe(content,{childList:true,subtree:true});document.addEventListener("click",e=>{if(e.target?.closest?.("[data-tab]"))setTimeout(decorate,35)},true);setInterval(decorate,1500)}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start,{once:true});else start();
})();
</script>
'''


def install(dashboard) -> bool:
    html = str(getattr(dashboard, "INDEX_HTML", "") or "")
    if not html or "</head>" not in html or "</body>" not in html:
        return False
    if 'id="sentrix-unified-adapter-v9-css"' not in html:
        html = html.replace("</head>", V9_CSS + "\n</head>", 1)
    if 'id="sentrix-unified-adapter-v9-js"' not in html:
        html = html.replace("</body>", V9_JS + "\n</body>", 1)
    dashboard.INDEX_HTML = html
    ok = (
        'id="sentrix-unified-adapter-v9-css"' in html
        and 'id="sentrix-unified-adapter-v9-js"' in html
        and 'Vérification Discord réelle' in html
        and 'CAPTCHA V96 RÉEL' in html
        and 'document.getElementById' in html
    )
    logger.warning(
        "Dashboard unified V2 adapter V9 installed=%s: real #content DOM + V96 verification panel.",
        ok,
    )
    return ok


__all__ = ["install", "V9_CSS", "V9_JS"]
